import { type TeamHuntState } from "@hunt/public-client";
import React, { useEffect, useMemo, useState } from "react";
import { hydrateRoot } from "react-dom/client";
import { terminusState as buildTerminusState } from "../rounds/dimensions/terminus";
import TerminusTravelLogEntryView, {
  type TerminusTravelLogEntryDetail,
} from "../rounds/dimensions/terminus/TravelLogEntryView";
import {
  buildTerminusResponseFromEntry,
  buildTerminusSnapshotState,
  loadTerminusLocalState,
} from "../rounds/dimensions/terminus/terminusLocalState";
import {
  type TerminusResponseState,
  type TerminusState,
} from "../rounds/dimensions/terminus/types";
import { IS_STATIC_SITE } from "../utils/staticSite";

const TerminusTravelLogEntryManager = ({
  initialEntry,
  initialTerminusState,
  initialTerminusResponse,
  initialTeamState,
}: {
  initialEntry: TerminusTravelLogEntryDetail | null;
  initialTerminusState: TerminusState | null;
  initialTerminusResponse: TerminusResponseState | null;
  initialTeamState: TeamHuntState;
}) => {
  const [entry, setEntry] = useState<TerminusTravelLogEntryDetail | null>(
    initialEntry,
  );
  const [terminusState, setTerminusState] = useState<TerminusState | null>(
    initialTerminusState,
  );
  const [terminusResponse, setTerminusResponse] =
    useState<TerminusResponseState | null>(initialTerminusResponse);
  const [loadFailed, setLoadFailed] = useState(false);

  const entryId = useMemo(() => {
    if (typeof window === "undefined") return null;
    const parts = window.location.pathname.split("/").filter(Boolean);
    const last = parts[parts.length - 1];
    const parsed = Number.parseInt(last ?? "", 10);
    return Number.isFinite(parsed) ? parsed : null;
  }, []);

  useEffect(() => {
    if (!IS_STATIC_SITE) return;
    if (!entryId) return;
    if (entry && terminusState && terminusResponse) return;
    let isActive = true;
    void (async () => {
      try {
        const localState = await loadTerminusLocalState();
        const found = localState.travelLog.find((item) => item.id === entryId);
        if (!found) {
          if (isActive) {
            setLoadFailed(true);
          }
          return;
        }
        if (!isActive) return;
        setLoadFailed(false);
        const detail: TerminusTravelLogEntryDetail = {
          ...found,
          formattedTimestamp: new Date(found.timestamp).toLocaleString(),
        };
        const baseState =
          terminusState ??
          buildTerminusState(initialTeamState, { username: "archival" });
        const snapshotState = buildTerminusSnapshotState(baseState, found);
        const response = buildTerminusResponseFromEntry(found);
        if (!isActive) return;
        setEntry(detail);
        setTerminusState(snapshotState);
        setTerminusResponse(response);
      } catch {
        // ignore
      }
    })();
    return () => {
      isActive = false;
    };
  }, [entry, entryId, initialTeamState, terminusResponse, terminusState]);

  if (!entry || !terminusState || !terminusResponse) {
    if (!entryId || loadFailed) {
      return (
        <div className="p-6 text-white font-body">
          Travel log entry not found.
        </div>
      );
    }
    return (
      <div className="p-6 text-white font-body">
        Loading travel log entry...
      </div>
    );
  }

  return (
    <TerminusTravelLogEntryView
      entry={entry}
      teamState={initialTeamState}
      terminusState={terminusState}
      initialTerminusResponse={terminusResponse}
    />
  );
};

const elem = document.getElementById("terminus-travel-log-entry-root");
if (elem) {
  const {
    initialTravelLogEntry,
    initialTerminusState,
    initialTerminusResponse,
    initialTeamState,
  } = window as unknown as {
    initialTravelLogEntry?: TerminusTravelLogEntryDetail | null;
    initialTerminusState?: TerminusState | null;
    initialTerminusResponse?: TerminusResponseState | null;
    initialTeamState: TeamHuntState;
  };

  hydrateRoot(
    elem,
    <TerminusTravelLogEntryManager
      initialEntry={initialTravelLogEntry ?? null}
      initialTerminusState={initialTerminusState ?? null}
      initialTerminusResponse={initialTerminusResponse ?? null}
      initialTeamState={initialTeamState}
    />,
  );
} else {
  console.error(
    "Could not mount TerminusTravelLogEntry because #terminus-travel-log-entry-root was nowhere to be found",
  );
}
