import { type TeamHuntState } from "@hunt/public-client";
import React from "react";
import {
  TerminusBackgroundWrapper,
  TerminusInteractiveScreens,
} from "./TerminusInterface/TerminusInterface";
import TerminusStars from "./TerminusInterface/TerminusStars";
import { TerminusMessages } from "./TerminusMessageBox/TerminusMessages";
import type { TerminusTravelLogEntry } from "./TravelLog";
import { type TerminusState, type TerminusResponseState } from "./types";

export type TerminusTravelLogEntryDetail = TerminusTravelLogEntry & {
  formattedTimestamp: string;
};

type TerminusTravelLogEntryViewProps = {
  entry: TerminusTravelLogEntryDetail;
  terminusState: TerminusState;
  initialTerminusResponse: TerminusResponseState | null;
  teamState: TeamHuntState;
};

const TerminusTravelLogEntryView: React.FC<TerminusTravelLogEntryViewProps> = ({
  terminusState,
  teamState,
  initialTerminusResponse,
}) => {
  return (
    <TerminusBackgroundWrapper
      backButtonProps={{
        text: "Back to Travel Log",
        href: "/rounds/terminus/travel_log",
      }}
      className="w-screen overflow-x-auto min-h-screen bg-term-light-blue"
    >
      <TerminusStars
        puzzles={terminusState.puzzles}
        response={initialTerminusResponse}
        teamState={teamState}
      />
      <TerminusInteractiveScreens
        response={initialTerminusResponse}
        state={terminusState}
        readOnly
      />
      <TerminusMessages response={initialTerminusResponse} />
    </TerminusBackgroundWrapper>
  );
};

export default TerminusTravelLogEntryView;
