import { NUM_FEEDERS_BY_ZONE, OVERWORLD_ROUND_SLUGS } from "@hunt/hunt-data";
import { type TeamHuntState } from "@hunt/public-client";
import { getPuzzleTitle, getTasks, PUZZLES } from "@hunt/puzzles";
import {
  type PuzzleRecord,
  type BasePuzzleDisplay,
  type BaseTaskDisplay,
  type PositionOnlyPuzzleRecord,
  type PuzzleSummary,
} from "./types";

export function getStubTitle(slug: string, isTask: boolean) {
  return `Stub ${isTask ? "task" : "puzzle"} for slot ${slug}`;
}

export function lookupSlug(
  slot: string,
  teamState: TeamHuntState,
  roundSlug: string,
): string | undefined {
  const round = teamState.rounds[roundSlug];
  const slotObj = round ? round.slots[slot] : undefined;
  return slotObj?.slug;
}

function buildPuzzleSummary(
  teamState: TeamHuntState,
  slug: string,
  roundSlug: string,
): PuzzleSummary | undefined {
  const puzzleState = teamState.puzzles[slug];
  if (!puzzleState) return undefined;
  const unlockState = puzzleState.locked;
  if (unlockState === "locked") return undefined;

  const puzzleDefinition = PUZZLES[slug];
  const roundSlot = Object.values(
    teamState.rounds[roundSlug]?.slots ?? {},
  ).find((slot) => slot.slug === slug);
  const title = puzzleDefinition
    ? getPuzzleTitle(puzzleDefinition, teamState)
    : getStubTitle(slug, roundSlug === "research_tasks");
  const is_meta = Boolean(roundSlot?.is_meta);
  const is_capstone = is_meta && OVERWORLD_ROUND_SLUGS.includes(roundSlug);

  return {
    title,
    slug,
    desc: puzzleDefinition?.initial_description,
    state: unlockState,
    answer: puzzleState.answer,
    unlock_cost: puzzleState.unlock_cost,
    nsfw: puzzleDefinition?.content.nsfw,
    physical_presence_requirement:
      puzzleDefinition?.content.physical_presence_requirement,
    is_overworld_feeder: puzzleState.is_overworld_feeder,
    is_meta,
    is_capstone,
  };
}

export function genPuzzleSummaries(
  teamState: TeamHuntState,
  roundSlug: string,
): PuzzleSummary[] {
  const round = teamState.rounds[roundSlug];
  if (!round) return [];

  return Object.values(round.slots)
    .filter(({ is_task }) => !is_task)
    .flatMap(({ slug }) => {
      if (!slug) return [];
      const summary = buildPuzzleSummary(teamState, slug, roundSlug);
      return summary ? [summary] : [];
    });
}

export function genPuzzles(
  teamState: TeamHuntState,
  roundSlug: string,
  slotToPuzzleData: Record<string, PuzzleRecord | PositionOnlyPuzzleRecord>,
  { immutable = false }: { immutable?: boolean },
): BasePuzzleDisplay[] {
  const round = teamState.rounds[roundSlug];
  if (!round) return [];

  return Object.entries(slotToPuzzleData).flatMap(([slotId, puzzleData]) => {
    const slug = lookupSlug(slotId, teamState, roundSlug);
    if (!slug) return [];

    const puzzle = buildPuzzleSummary(teamState, slug, roundSlug);
    if (!puzzle) return [];
    const state = puzzle.state;

    return [
      {
        pos: puzzleData.pos,
        region: puzzleData.region,
        asset:
          "asset" in puzzleData
            ? puzzleData.asset[!!puzzle.answer || immutable ? "solved" : state]
            : "",
        puzzle,
      },
    ];
  });
}

export function genTasks(
  teamState: TeamHuntState,
  roundSlug: string,
): BaseTaskDisplay[] {
  const round = teamState.rounds[roundSlug];
  if (!round) {
    return [];
  }

  const tasksBySlug = getTasks();

  return Object.entries(round.slots).flatMap(([slotId, { slug }]) => {
    if (!slug) return [];
    const puzzleState = teamState.puzzles[slug];
    if (!puzzleState?.task_info) return [];

    const taskDefinition = tasksBySlug[slug];
    const title = taskDefinition
      ? getPuzzleTitle(taskDefinition, teamState)
      : getStubTitle(slotId, true);

    const desc = taskDefinition?.initial_description;

    const state = puzzleState.locked === "unlocked" ? "unlocked" : "locked";

    const prizeMax = puzzleState.task_info.prize_options
      ? Math.max(...Object.values(puzzleState.task_info.prize_options))
      : undefined;
    // Interactive tasks should be treated the same as auto tasks on the
    // tasks list and on the individual task page.
    return [
      {
        slug,
        title,
        desc,
        state,
        answer: puzzleState.answer,
        prize: puzzleState.prize ?? 0,
        prizeMax: prizeMax,
        solved: Boolean(puzzleState.solved),
        submissionType:
          puzzleState.task_info.submission_type === "interactive"
            ? "auto"
            : puzzleState.task_info.submission_type,
        taskSubmissionState: puzzleState.task_submission_state,
        replayable: puzzleState.task_info.replayable,
      },
    ];
  });
}

export function areAllFeedersDiscovered(
  teamState: TeamHuntState,
  roundSlug: string,
  puzzles: PuzzleSummary[],
): boolean {
  const round = teamState.rounds[roundSlug];
  if (!round) {
    return false;
  }

  const totalFeeders = NUM_FEEDERS_BY_ZONE[roundSlug];

  if (totalFeeders === 0) {
    return false;
  }

  const discoveredFeeders = puzzles.filter(
    (puz) => puz.is_overworld_feeder,
  ).length;

  return discoveredFeeders >= totalFeeders;
}
