import { TERMINUS_META_SLUGS } from "@hunt/hunt-data";
import type { TeamHuntState, TeamInfo } from "@hunt/public-client";
import React from "react";
import teamIsImmutable from "../../../../utils/teamIsImmutable";
import { getCutsceneFromTeamState } from "../../../components/cutscene/get_cutscene_from_teamstate";
import { genPuzzles } from "../../utils";
import TerminusBody from "./TerminusBody";
import { SLOT_TO_PUZZLE_DATA } from "./terminus_slot_data";
import type { TerminusResponseState, TerminusState } from "./types";

export function terminusState(
  teamState: TeamHuntState,
  { username }: { username: string },
): TerminusState {
  const immutable = teamIsImmutable(username);

  const puzzles = genPuzzles(teamState, "terminus", SLOT_TO_PUZZLE_DATA, {
    immutable,
  });
  const puzzlesWithMeta = puzzles.map((puzzle) => ({
    ...puzzle,
    is_meta: TERMINUS_META_SLUGS.includes(puzzle.puzzle.slug),
    is_final_meta: puzzle.puzzle.slug === "mixed_media",
  }));
  const unlocked = puzzlesWithMeta
    .filter((puzzle) => puzzle.puzzle.state === "unlocked")
    .map((puzzle) => puzzle.puzzle.slug);
  const solved = puzzlesWithMeta
    .filter((puzzle) => Boolean(puzzle.puzzle.answer))
    .map((puzzle) => puzzle.puzzle.slug);

  const metaSlug = teamState.rounds.terminus.slots.tm07?.slug;
  const meta = metaSlug
    ? (puzzlesWithMeta.find((puzzle) => puzzle.puzzle.slug === metaSlug) ??
      null)
    : null;
  const metaState = metaSlug ? teamState.puzzles[metaSlug] : undefined;

  return {
    epoch: teamState.epoch,
    puzzles: puzzlesWithMeta,
    progress: {
      unlocked,
      solved,
    },
    meta: metaState?.locked === "unlocked" ? meta : null,
  };
}

export const getTerminusState = (
  teamState: TeamHuntState,
  teamInfo: TeamInfo,
) => terminusState(teamState, { username: teamInfo.teamUsername });

const TerminusRoundPage = ({
  teamState,
  teamInfo,
  initialTerminusResponse,
}: {
  teamState: TeamHuntState;
  teamInfo: TeamInfo;
  initialTerminusResponse?: TerminusResponseState | null;
}) => {
  const state = getTerminusState(teamState, teamInfo);
  const cutsceneContent = [];

  const startCutscene = getCutsceneFromTeamState("terminus", "tc01", teamState);
  if (startCutscene) {
    cutsceneContent.push(startCutscene);
  }

  const scriptParts = [
    `window.initialTerminusState = ${JSON.stringify(state)};`,
    `window.initialTeamState = ${JSON.stringify(teamState)};`,
    `window.initialCutsceneContent = ${JSON.stringify(cutsceneContent)};`,
  ];
  if (initialTerminusResponse !== undefined) {
    scriptParts.push(
      `window.initialTerminusResponse = ${JSON.stringify(initialTerminusResponse)};`,
    );
  }
  const inlineScript = scriptParts.join(" ");
  return (
    <>
      <script dangerouslySetInnerHTML={{ __html: inlineScript }} />
      <div id="terminus-root">
        <TerminusBody
          state={state}
          teamState={teamState}
          initialTerminusResponse={initialTerminusResponse}
          cutsceneContent={cutsceneContent}
        />
      </div>
    </>
  );
};

export default TerminusRoundPage;
