import { alphaObfuscateString } from "@hunt/alpha-round";
import { CUTSCENE_DATA } from "@hunt/hunt-data/cutscenes";
import { type TeamHuntState } from "@hunt/public-client";
import { type ResolvedCutsceneContent } from "@hunt/puzzle-components";

export const getCutsceneFromTeamState = (
  roundSlug: string,
  cutsceneId: string,
  teamState: TeamHuntState,
): ResolvedCutsceneContent | undefined => {
  if (!teamState.rounds[roundSlug]?.interactions?.[cutsceneId]) {
    return undefined;
  }

  if (!(cutsceneId in CUTSCENE_DATA)) {
    return undefined;
  }

  const cutscene = CUTSCENE_DATA[cutsceneId as keyof typeof CUTSCENE_DATA];
  if (!cutscene) {
    throw new Error(`Cutscene ${cutsceneId} not found`);
  }

  return {
    ...cutscene,
    dialogue: cutscene.dialogue.map((dialogue) => {
      let dialogueText = undefined;
      if (dialogue.text) {
        dialogueText =
          typeof dialogue.text === "string"
            ? dialogue.text
            : dialogue.text
                .map((text) =>
                  text.obfuscate
                    ? alphaObfuscateString(text.text, teamState)
                    : text.text,
                )
                .join(" ");
      }
      return { ...dialogue, text: dialogueText };
    }),
  };
};
