import { PUZZLE_SLUGS_TO_PUZZMON_SLUGS } from "@hunt/hunt-data";
import type { TeamHuntState } from "@hunt/public-client";
import { DEFAULT_VOLUME, VOLUME_STORAGE_KEY } from "@hunt/puzzle-components";
import React from "react";
import taskSolveSound from "../../api/assets/solve_sounds/solve-task.mp3";
import type { AllPuzzlesState } from "../client/all_puzzles_types";
import { type ResearchTasksState } from "../client/research_tasks_types";

const SOLVED_PUZZLES_KEY = "hunt.puzzles.solved.v1";
const LOCAL_STATE_EVENT = "hunt.puzzles.solved.updated";

export type LocalSolvedPuzzleEntry = {
  answer?: string;
  puzzmonSlug?: string;
};

export type LocalSolvedPuzzleMap = Record<string, LocalSolvedPuzzleEntry>;

const canUseStorage = () =>
  typeof window !== "undefined" && typeof window.localStorage !== "undefined";

const parseSolvedMap = (raw: string | null): LocalSolvedPuzzleMap => {
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (Array.isArray(parsed)) {
      return parsed.reduce<LocalSolvedPuzzleMap>((acc, slug) => {
        if (typeof slug === "string") {
          acc[slug] = {};
        }
        return acc;
      }, {});
    }
    if (!parsed || typeof parsed !== "object") return {};
    const map: LocalSolvedPuzzleMap = {};
    for (const [slug, entry] of Object.entries(parsed)) {
      if (!slug) continue;
      if (entry && typeof entry === "object") {
        const answer = (entry as { answer?: unknown }).answer;
        const puzzmonSlug = (entry as { puzzmonSlug?: unknown }).puzzmonSlug;
        map[slug] = {
          answer: typeof answer === "string" ? answer : undefined,
          puzzmonSlug:
            typeof puzzmonSlug === "string" ? puzzmonSlug : undefined,
        };
      } else {
        map[slug] = {};
      }
    }
    return map;
  } catch {
    return {};
  }
};

const dispatchLocalSolvedEvent = () => {
  if (typeof window === "undefined") return;
  window.dispatchEvent(new Event(LOCAL_STATE_EVENT));
};

export const getLocalSolvedPuzzleMap = (): LocalSolvedPuzzleMap => {
  if (!canUseStorage()) return {};
  return parseSolvedMap(window.localStorage.getItem(SOLVED_PUZZLES_KEY));
};

const setLocalSolvedPuzzleMap = (map: LocalSolvedPuzzleMap) => {
  if (!canUseStorage()) return;
  try {
    window.localStorage.setItem(SOLVED_PUZZLES_KEY, JSON.stringify(map));
    dispatchLocalSolvedEvent();
  } catch {
    // Ignore storage failures.
  }
};

export const markPuzzleSolved = (slug: string, answer?: string): boolean => {
  if (!canUseStorage() || !slug) return false;
  const existing = getLocalSolvedPuzzleMap();
  const current = existing[slug];
  const nextAnswer = answer ?? current?.answer;
  const hasChange =
    !current ||
    (typeof nextAnswer === "string" && current.answer !== nextAnswer);
  if (!hasChange) return false;
  const puzzmonSlug = PUZZLE_SLUGS_TO_PUZZMON_SLUGS.get(slug);
  existing[slug] = { answer: nextAnswer, puzzmonSlug: puzzmonSlug };
  setLocalSolvedPuzzleMap(existing);
  return true;
};

/**
 * Marks a task as solved in localStorage and plays the task solve sound.
 * Use this for interactive research tasks that aren't completed via entering an answer,
 * since this function plays the task solve sound additionally too.
 * Volume is read from localStorage (VOLUME_STORAGE_KEY) or defaults to DEFAULT_VOLUME.
 */
export const markTaskSolved = (slug: string): boolean => {
  const changed = markPuzzleSolved(slug);
  if (typeof window !== "undefined") {
    try {
      const stored = window.localStorage.getItem(VOLUME_STORAGE_KEY);
      const volume = Number(stored ?? DEFAULT_VOLUME);
      const audio = new Audio(taskSolveSound);
      audio.volume = volume;
      void audio.play();
    } catch {
      // Ignore when Audio or play not available
    }
  }
  return changed;
};

export const addSolvedPuzzles = (
  entries: { slug: string; answer?: string }[],
): boolean => {
  if (!canUseStorage()) return false;
  const existing = getLocalSolvedPuzzleMap();
  let changed = false;
  entries.forEach(({ slug, answer }) => {
    if (!slug) return;
    const current = existing[slug];
    const nextAnswer = answer ?? current?.answer;
    if (!current || (nextAnswer && current.answer !== nextAnswer)) {
      existing[slug] = { answer: nextAnswer };
      changed = true;
    }
  });
  if (changed) {
    setLocalSolvedPuzzleMap(existing);
  }
  return changed;
};

export const removeSolvedPuzzles = (slugs: string[]): boolean => {
  if (!canUseStorage()) return false;
  const existing = getLocalSolvedPuzzleMap();
  const removeSet = new Set(slugs);
  if (removeSet.size === 0) return false;
  let changed = false;
  const next: LocalSolvedPuzzleMap = {};
  Object.entries(existing).forEach(([slug, entry]) => {
    if (removeSet.has(slug)) {
      changed = true;
      return;
    }
    next[slug] = entry;
  });
  if (changed) {
    setLocalSolvedPuzzleMap(next);
  }
  return changed;
};

export const resetSolvedPuzzles = (): boolean => {
  if (!canUseStorage()) return false;
  setLocalSolvedPuzzleMap({});
  return true;
};

export const mergeSolvedAnswer = (
  slug: string,
  currentAnswer: string | undefined,
  solvedMap: LocalSolvedPuzzleMap,
): string | undefined => {
  if (currentAnswer !== undefined) return currentAnswer;
  const entry = solvedMap[slug];
  if (!entry) return currentAnswer;
  return entry.answer ?? "Solved";
};

export const applySolvedMapToPuzzleSummaries = <
  T extends { slug: string; answer?: string },
>(
  puzzles: T[],
  solvedMap: LocalSolvedPuzzleMap,
): T[] => {
  if (!puzzles.length || Object.keys(solvedMap).length === 0) {
    return puzzles;
  }
  let changed = false;
  const updated = puzzles.map((puzzle) => {
    const nextAnswer = mergeSolvedAnswer(puzzle.slug, puzzle.answer, solvedMap);
    if (nextAnswer === puzzle.answer) return puzzle;
    changed = true;
    return { ...puzzle, answer: nextAnswer };
  });
  return changed ? updated : puzzles;
};

export const applySolvedMapToPuzzleDisplays = <
  T extends { puzzle: { slug: string; answer?: string } },
>(
  puzzles: T[],
  solvedMap: LocalSolvedPuzzleMap,
): T[] => {
  if (!puzzles.length || Object.keys(solvedMap).length === 0) {
    return puzzles;
  }
  let changed = false;
  const updated = puzzles.map((puzzle) => {
    const nextAnswer = mergeSolvedAnswer(
      puzzle.puzzle.slug,
      puzzle.puzzle.answer,
      solvedMap,
    );
    if (nextAnswer === puzzle.puzzle.answer) return puzzle;
    changed = true;
    return {
      ...puzzle,
      puzzle: {
        ...puzzle.puzzle,
        answer: nextAnswer,
      },
    };
  });
  return changed ? updated : puzzles;
};

export const applySolvedMapToAllPuzzlesState = (
  state: AllPuzzlesState,
  solvedMap: LocalSolvedPuzzleMap,
): AllPuzzlesState => {
  if (Object.keys(solvedMap).length === 0) {
    return state;
  }
  return {
    ...state,
    rounds: state.rounds.map((round) => ({
      ...round,
      puzzles: applySolvedMapToPuzzleSummaries(round.puzzles, solvedMap),
    })),
  };
};

export const applySolvedMapToTeamState = (
  teamState: TeamHuntState,
  solvedMap: LocalSolvedPuzzleMap,
): TeamHuntState => {
  if (Object.keys(solvedMap).length === 0) {
    return teamState;
  }
  let changed = false;
  const puzzles = { ...teamState.puzzles };
  Object.entries(solvedMap).forEach(([slug]) => {
    const puzzle = puzzles[slug];
    if (!puzzle) return;
    const nextAnswer = mergeSolvedAnswer(slug, puzzle.answer, solvedMap);
    if (nextAnswer === puzzle.answer && puzzle.solved) return;
    puzzles[slug] = {
      ...puzzle,
      answer: nextAnswer ?? puzzle.answer,
      solved: true,
    };
    changed = true;
  });
  if (!changed) return teamState;
  return {
    ...teamState,
    puzzles,
  };
};

export const useSolvedPuzzlesState = () => {
  const [solvedMap, setSolvedMap] = React.useState<LocalSolvedPuzzleMap>(() =>
    getLocalSolvedPuzzleMap(),
  );

  React.useEffect(() => {
    if (!canUseStorage()) return;
    const handleStorage = (event: StorageEvent) => {
      if (event.key === SOLVED_PUZZLES_KEY) {
        setSolvedMap(getLocalSolvedPuzzleMap());
      }
    };
    const handleLocal = () => {
      setSolvedMap(getLocalSolvedPuzzleMap());
    };
    window.addEventListener(LOCAL_STATE_EVENT, handleLocal);
    window.addEventListener("storage", handleStorage);
    return () => {
      window.removeEventListener(LOCAL_STATE_EVENT, handleLocal);
      window.removeEventListener("storage", handleStorage);
    };
  }, []);

  const solvedSlugs = React.useMemo(() => Object.keys(solvedMap), [solvedMap]);

  return { solvedMap, solvedSlugs };
};

export const applySolvedMapToResearchTasksState = (
  state: ResearchTasksState,
  solvedMap: LocalSolvedPuzzleMap,
): ResearchTasksState => {
  if (Object.keys(solvedMap).length === 0) {
    return state;
  }
  return {
    ...state,
    tasks: applySolvedMapToResearchTasks(state.tasks, solvedMap),
  };
};

export const applySolvedMapToResearchTasks = <
  T extends { slug: string; answer?: string; solved?: boolean },
>(
  tasks: T[],
  solvedMap: LocalSolvedPuzzleMap,
): T[] => {
  if (!tasks.length || Object.keys(solvedMap).length === 0) {
    return tasks;
  }
  let changed = false;
  const updated = tasks.map((task) => {
    const nextAnswer = mergeSolvedAnswer(task.slug, task.answer, solvedMap);
    const isSolved = Boolean(task.solved) || solvedMap[task.slug] !== undefined;
    if (nextAnswer === task.answer && task.solved === isSolved) return task;
    changed = true;
    return { ...task, answer: nextAnswer, solved: isSolved };
  });
  return changed ? updated : tasks;
};
